# New reusable analysis entry. Requires a CURRENT verified native input record and manually inspected masks.
import argparse,json,hashlib,time,importlib.metadata as md
from pathlib import Path
import numpy as np
from PIL import Image,ImageDraw
import torch
from transformers import AutoImageProcessor,AutoModelForDepthEstimation
ap=argparse.ArgumentParser();ap.add_argument('--input-record',required=True);ap.add_argument('--model-root',required=True);ap.add_argument('--output',required=True);args=ap.parse_args();record=json.load(open(args.input_record));source=Path(record['file']);modelroot=Path(args.model_root);out=Path(args.output);out.mkdir(parents=True,exist_ok=True)
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
assert record['role']=='current_verified_native_frame','Historical preview/model render is NOT a native input'
assert sha(source)==record['sha256'];img=Image.open(source).convert('RGB');assert list(img.size)==record['dimensions'];assert 'manual_masks' in record,'Review current original pixels before supplying masks'
torch.set_num_threads(2);torch.set_num_interop_threads(1);proc=AutoImageProcessor.from_pretrained(modelroot,local_files_only=True,trust_remote_code=False,use_fast=False);model=AutoModelForDepthEstimation.from_pretrained(modelroot,local_files_only=True,trust_remote_code=False,use_safetensors=True).eval();inputs=proc(images=img,return_tensors='pt');t=time.time()
with torch.inference_mode():raw=model(**inputs).predicted_depth[0].cpu().numpy().astype('float32')
np.save(out/'relative-inverse-depth-model-grid.npy',raw,allow_pickle=False);valid=np.isfinite(raw);lo=float(raw[valid].min());hi=float(raw[valid].max());gray=np.where(valid,np.clip((raw-lo)/max(hi-lo,1e-12),0,1)*65535,0).round().astype('uint16');Image.fromarray(gray).save(out/'relative-inverse-depth-gray16-model-grid.png');scaled=torch.nn.functional.interpolate(torch.from_numpy(raw)[None,None],size=(img.height,img.width),mode='bicubic',align_corners=False)[0,0].numpy();Image.fromarray((np.clip((scaled-lo)/max(hi-lo,1e-12),0,1)*255).round().astype('uint8')).save(out/'relative-inverse-depth-gray8-resampled-source-grid.png')
mask=Image.new('L',img.size);draw=ImageDraw.Draw(mask)
for roi in record['manual_masks']:draw.polygon([tuple(x) for x in roi['points']],fill=roi['class_id'])
mask.save(out/'manual-exclusion-classes-source-grid.png');Image.new('L',img.size,255).save(out/'confidence-UNKNOWN-source-grid.png');panel=Image.new('RGB',(960,540));a=img.copy();a.thumbnail((480,540));b=Image.open(out/'relative-inverse-depth-gray8-resampled-source-grid.png').convert('RGB');b.thumbnail((480,540));panel.paste(a,(0,0));panel.paste(b,(480,0));panel.save(out/'source-and-relative-depth-display.jpg',quality=94)
report={'source':record,'method':{'model':'depth-anything/Depth-Anything-V2-Small-hf','revision':record['model_revision'],'weights_sha256':sha(modelroot/'model.safetensors'),'processor_config':json.load(open(modelroot/'preprocessor_config.json')),'versions':{x:md.version(x) for x in ['torch','transformers','safetensors','pillow','numpy']},'device':'cpu','threads':2,'dtype':'float32','local_files_only':True,'trust_remote_code':False,'input_tensor_shape':list(inputs['pixel_values'].shape),'raw_output_shape':list(raw.shape),'inference_and_output_seconds':time.time()-t},'definition':'relative inverse-depth-like model output, larger generally nearer; not metric distance or luminance','range':{'min':lo,'max':hi,'nonfinite_count':int((~valid).sum())},'normalization':'per-image (raw-min)/(max-min), larger white=nearer; source-grid image is bicubic resampling only, never native prediction','confidence':'model provides no calibrated confidence; 255 UNKNOWN everywhere, not high confidence','mask_semantics':record['mask_semantics'],'limits':['manual mask labels not exhaustive; label0 is unlabelled, NOT reliable','reflection/water/sky/particles/characters and hidden structures can fail','no cross-image metric comparison, real dimensions/contact/unique camera or source acceptance established']};report['outputs']=[{'file':p.name,'bytes':p.stat().st_size,'sha256':sha(p)} for p in sorted(out.iterdir()) if p.is_file()];(out/'report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2));print(json.dumps(report['method'],indent=2))
